import Foundation
@testable import RelayMarkEditor
import Testing
import RelayMarkCollaboration
import RelayMarkNativeCollaboration
import RelayMarkSwift
import RelayMarkProseProjection

@MainActor
struct RelayMarkEditorInlineMarkTests {
    // Actual Chromium StarterKit/Yjs seed, generated by RelayMark's
    // scripts/collaboration-inline-mark-fixture.mjs; no app-owned mark schema.
    private let seed = "AQmf99+bAQAHAQdkZWZhdWx0AwlwYXJhZ3JhcGgHAJ/335sBAAYGAJ/335sBAQZzdHJpa2UCe32En/ffmwECC1N0cmlrZSDwn4yNhp/335sBCwZzdHJpa2UEbnVsbISf99+bAQwHIHBsYWluIIaf99+bARMEY29kZQJ7fYSf99+bARQMY29kZSBgIHZhbHVlhp/335sBIARjb2RlBG51bGwA"
    private func document() throws -> RelayMarkNativeDocument {
        let document = RelayMarkNativeDocument()
        try document.applyUpdate(try #require(Data(base64Encoded: seed)))
        #expect(throws: (any Error).self) { try document.authoredDocument() }
        let retained = try RelayMarkNativeSnapshotImport.prepare(document: document,
            namespace: "retained-browser-inline-marks", expectedSnapshot: document.snapshot())
        let exactOriginalEvidence = [retained.originalState, retained.result]
        #expect(exactOriginalEvidence[0] == Data(base64Encoded: seed))
        _ = try RelayMarkNativeSnapshotImport.install(document: document, prepared: retained)
        _ = try document.authoredDocument()
        return document
    }

    @Test func browserFixtureCodeExclusionUndoAndPeerAnchors() throws {
        let document = try document(), peer = RelayMarkNativeDocument()
        try peer.applyUpdate(document.encodeUpdate())
        var saved: [RelayMarkLocalTransaction] = []
        let editor = try RelayMarkEditorSession(document: document, persist: { saved.append($0) })
        editor.setNativeSelection(NSRange(location: 0, length: 9))
        let selection = try #require(try editor.selectionRelativeRange())
        editor.toggleInlineMark(.code)
        #expect(editor.failure == nil && saved.count == 1)
        #expect(editor.text.runs.first?.inlinePresentationIntent == .code)
        try peer.applyUpdate(try #require(saved.last).update)
        #expect(try editor.resolveRelativeRange(selection) == NSRange(location: 0, length: 9))
        let update = try RelayMarkNativeRichTextMutation.replace(document: peer, path: [0,0], start: 0, end: 0,
            text: "Peer ", attributes: [:])
        try editor.applyRemoteUpdate(update)
        editor.undo()
        #expect(editor.failure == nil && saved.count == 2, "failure=\(editor.failure ?? "none"), saves=\(saved.count), selection=\(String(describing: editor.nativeSelection))")
        try peer.applyUpdate(try #require(saved.last).update)
        #expect(String(editor.text.characters).hasPrefix("Peer Strike 🌍"))
        #expect(editor.text.runs.contains { ($0.inlinePresentationIntent ?? []).contains(.strikethrough) })
        editor.redo()
        try peer.applyUpdate(try #require(saved.last).update)
        #expect(relayPaperInlineSemantics(try peer.richProseProjection().text) == relayPaperInlineSemantics(editor.text))
        #expect(NativeProseCodec.value(NativeProseCodec.attributed(editor.text)) == editor.text)
    }

    /// A mark command at a caret marks the next characters typed there, as the web's
    /// stored marks do; the same command again turns it back off. Nothing is written
    /// until text is typed.
    @Test(arguments: [RelayMarkFormattingMark.bold, .italic, .strike, .code])
    func aMarkAtTheCaretMarksTheNextTypedText(mark: RelayMarkFormattingMark) throws {
        let document = RelayMarkNativeDocument()
        _ = try document.initializeDocument(authoredAST: RelayMarkSourceCodec.parseDocument("Hello", namespace: "caret-marks"))
        var saved: [RelayMarkLocalTransaction] = []
        let editor = try RelayMarkEditorSession(document: document, persist: { saved.append($0) })
        editor.setNativeSelection(NSRange(location: 5, length: 0))
        editor.toggleInlineMark(mark)
        #expect(saved.isEmpty && editor.failure == nil)
        #expect(editor.typeNatively(range: NSRange(location: 5, length: 0), replacement: " marked"))
        editor.toggleInlineMark(mark)
        #expect(editor.typeNatively(range: NSRange(location: 12, length: 0), replacement: " plain"))
        let runs = editor.text.runs.map { (String(editor.text[$0.range].characters), $0.inlinePresentationIntent ?? []) }
        #expect(runs.map(\.0) == ["Hello", " marked", " plain"], "\(runs)")
        #expect(runs.map { $0.1.contains(mark.inlineIntent) } == [false, true, false])
    }

    @Test func strikeReplacesCodeAtomicallyAndClearsOnSecondCommand() throws {
        let document = try document()
        var saved: [RelayMarkLocalTransaction] = []
        let editor = try RelayMarkEditorSession(document: document, persist: { saved.append($0) })
        editor.setNativeSelection(NSRange(location: 16, length: 12))
        editor.toggleInlineMark(.strike)
        #expect(editor.failure == nil && saved.count == 1)
        #expect(editor.text.runs.last?.inlinePresentationIntent == .strikethrough)
        #expect(editor.nativeSelection == NSRange(location: 16, length: 12))
        editor.toggleInlineMark(.strike)
        #expect(editor.failure == nil && saved.count == 2, "failure=\(editor.failure ?? "none"), saves=\(saved.count), selection=\(String(describing: editor.nativeSelection))")
        let remainingIntent = editor.text.runs.last?.inlinePresentationIntent ?? []
        #expect(remainingIntent.contains(.strikethrough) == false)
    }

    @Test func inlineCodeRemovesLinkWithoutChangingTextOrAnchor() throws {
        let document = RelayMarkNativeDocument()
        _ = try document.initializeDocument(authoredAST: RelayMarkSourceCodec.parseDocument(
            "**[Reference](https://example.org/reference)**", namespace: "current-inline-link"))
        let before = try document.richProseProjection().text
        #expect(String(before.characters) == "Reference")
        #expect(before.runs.allSatisfy { $0.link?.absoluteString == "https://example.org/reference" })
        let anchor = try document.anchor(path: [0, 0], index: 5)
        var saved: [RelayMarkLocalTransaction] = []
        let editor = try RelayMarkEditorSession(document: document, persist: { saved.append($0) })
        editor.setNativeSelection(NSRange(location: 0, length: 9)); editor.toggleInlineMark(.code)
        #expect(editor.failure == nil && saved.count == 1)
        #expect(editor.text.runs.allSatisfy { $0.link == nil && $0.inlinePresentationIntent == .code })
        #expect(try document.resolve(anchor: anchor)?.index == 5)
    }

    @Test func invalidUnicodeMultilineAndIMEFormattingNeverMutateDocument() throws {
        let document = RelayMarkNativeDocument()
        _ = try document.initializeDocument(authoredAST: RelayMarkSourceCodec.parseDocument(
            "A🌍\nB", namespace: "current-inline-unicode"))
        var saved: [RelayMarkLocalTransaction] = []
        let editor = try RelayMarkEditorSession(document: document, persist: { saved.append($0) })
        let baseline = try document.encodeUpdate()
        editor.setNativeSelection(NSRange(location: 2, length: 1)); editor.toggleInlineMark(.strike)
        editor.setNativeSelection(NSRange(location: 0, length: 5)); editor.toggleInlineMark(.code)
        #expect(try document.encodeUpdate() == baseline && saved.isEmpty)
        editor.setNativeSelection(NSRange(location: 0, length: 1))
        let token = try editor.beginComposition()
        editor.toggleInlineMark(.strike)
        #expect(try document.encodeUpdate() == baseline && saved.isEmpty)
        try editor.commitComposition(AttributedString("日本🌍\nB"), from: token)
        #expect(editor.failure == nil && saved.count == 1)
        #expect(String(editor.text.characters) == "日本🌍\nB")
    }
    @Test func committedIMEPreservesExistingInlineCode() throws {
        let document = RelayMarkNativeDocument()
        _ = try document.initializeDocument(authoredAST: RelayMarkSourceCodec.parseDocument(
            "`code`", namespace: "current-inline-ime"))
        var saved: [RelayMarkLocalTransaction] = []
        let editor = try RelayMarkEditorSession(document: document, persist: { saved.append($0) })
        let token = try editor.beginComposition()
        var candidate = AttributedString("cあde")
        candidate.inlinePresentationIntent = .code
        try editor.commitComposition(candidate, from: token)
        #expect(editor.failure == nil && saved.count == 1)
        #expect(String(editor.text.characters) == "cあde")
        #expect(editor.text.runs.allSatisfy { $0.inlinePresentationIntent == .code })
    }



}
